export function seeded(seed){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return ((t^(t>>>14))>>>0)/4294967296;};}
export function shuffle(items,rng){const out=[...items];for(let i=out.length-1;i>0;i--){let j=Math.floor(rng()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;}
export function newCase(seed=Date.now()){const rng=seeded(seed);return {version:1,seed,caseCode:`MMA-${(seed>>>0).toString(36).toUpperCase().slice(-5)}`,route:shuffle(Object.keys(CITIES),rng),culprit:SUSPECTS[Math.floor(rng()*SUSPECTS.length)].id,evidenceOrder:shuffle(['accessory','seal','mark'],rng),suspectOrder:shuffle(SUSPECTS.map(s=>s.id),rng),optionOrders:Object.fromEntries(Object.entries(CITIES).map(([k,v])=>[k,shuffle(v.options.map(o=>o.id),rng)])),chapter:0,phase:'briefing',evidence:[],witnessRead:false,learned:[],solved:false,startedAt:new Date().toISOString()};}
export function culpritOf(s){return SUSPECTS.find(p=>p.id===s.culprit);}
export function clueFor(s,chapter=s.chapter){let kind=s.evidenceOrder[chapter];let p=culpritOf(s);return {kind,value:p[kind],city:s.route[chapter],text:kind==='accessory'?`The visitor wore ${p[kind]}.`:kind==='seal'?`The wax seal on the music case showed ${p[kind]}.`:`The visitor’s case had ${p[kind]}.`};}
export function matchingSuspects(evidence){return SUSPECTS.filter(p=>evidence.every(e=>p[e.kind]===e.value));}
export function validSave(s){
 if(!s || s.version!==1 || !Number.isInteger(s.seed) || typeof s.caseCode!=='string'||!/^MMA-[A-Z0-9]{1,5}$/.test(s.caseCode))return false;
 if(!Array.isArray(s.route)||s.route.length!==3||new Set(s.route).size!==3||!s.route.every(id=>Object.hasOwn(CITIES,id)))return false;
 if(!SUSPECTS.some(p=>p.id===s.culprit)||!Number.isInteger(s.chapter)||s.chapter<0||s.chapter>2)return false;
 if(!['briefing','investigate','question','route','finale','solved'].includes(s.phase)||typeof s.solved!=='boolean')return false;
 if(s.phase==='route'&&s.chapter===2)return false;
 if(!Array.isArray(s.learned)||!s.learned.every(x=>TERMS.some(t=>t.id===x)))return false;
 if(!Array.isArray(s.evidenceOrder)||s.evidenceOrder.length!==3||new Set(s.evidenceOrder).size!==3||!s.evidenceOrder.every(x=>['accessory','seal','mark'].includes(x)))return false;
 if(!Array.isArray(s.suspectOrder)||s.suspectOrder.length!==4||new Set(s.suspectOrder).size!==4||!s.suspectOrder.every(id=>SUSPECTS.some(p=>p.id===id)))return false;
 if(!s.optionOrders||!Object.entries(CITIES).every(([id,c])=>Array.isArray(s.optionOrders[id])&&s.optionOrders[id].length===3&&new Set(s.optionOrders[id]).size===3&&s.optionOrders[id].every(x=>c.options.some(o=>o.id===x))))return false;
 if(!Array.isArray(s.evidence)||s.evidence.length>3||!s.evidence.every((e,i)=>e&&e.kind===s.evidenceOrder[i]&&e.value===culpritOf(s)[e.kind]&&e.city===s.route[i]&&e.text===clueFor(s,i).text))return false;
 if(s.phase==='finale'||s.phase==='solved')return s.evidence.length===3;
 return s.evidence.length===(s.phase==='route'?s.chapter+1:s.chapter);
}
